<?php
require_once 'includes/config.php'; require_once 'includes/phase1.php'; require_once 'includes/phase3.php'; require_admin();
$msg = null;
$error = null;$msg='';$error='';
function approve_submission(PDO $dbh,int $id,int $adminId): void { $dbh->beginTransaction();try{$q=$dbh->prepare("UPDATE result_submissions SET submission_status='approved',approval_state='approved',reviewed_by=:a,reviewed_at=NOW(),updated_at=NOW() WHERE id=:id AND submission_status='pending'");$q->execute([':a'=>$adminId,':id'=>$id]);if($q->rowCount()<1)throw new RuntimeException('Only pending submissions can be approved.');$r=$dbh->prepare("UPDATE tblresult SET result_status='approved',approval_state='approved',approved_by=:a,approved_at=NOW(),rejection_reason=NULL,Published=0,published_by=NULL,published_at=NULL,UpdationDate=NOW() WHERE submission_id=:id");$r->execute([':a'=>$adminId,':id'=>$id]);$dbh->commit();}catch(Throwable $x){if($dbh->inTransaction())$dbh->rollBack();throw $x;}}
if($_SERVER['REQUEST_METHOD']==='POST'){$action=$_POST['action']??'';$id=(int)($_POST['id']??0);try{if($action==='approve'){approve_submission($dbh,$id,(int)$_SESSION['admin_id']);$msg='Submission approved. It is still unpublished until an administrator publishes it.';audit_log($dbh,'RESULT_APPROVE','Submission '.$id); $n=$dbh->prepare('SELECT teacher_id,student_id,academic_year,term,exam_type FROM result_submissions WHERE id=:id');$n->execute([':id'=>$id]);if($nr=$n->fetch()){ $sq=$dbh->prepare('SELECT StudentName FROM tblstudents WHERE StudentId=:s');$sq->execute([':s'=>$nr['student_id']]);$sn=$sq->fetchColumn()?:'student'; notify_teacher($dbh,(int)$nr['teacher_id'],'Result approved','Your result for '.$sn.' ('.$nr['academic_year'].' / '.$nr['term'].' / '.$nr['exam_type'].') has been approved by the administrator.','success','teacher-submissions.php'); }}
elseif($action==='reject'){$reason=trim($_POST['reason']??'');if(!$reason)throw new RuntimeException('A rejection reason is required.');$dbh->beginTransaction();$q=$dbh->prepare("UPDATE result_submissions SET submission_status='rejected',approval_state='rejected',reviewed_by=:a,reviewed_at=NOW(),rejection_reason=:r,updated_at=NOW() WHERE id=:id AND submission_status='pending'");$q->execute([':a'=>$_SESSION['admin_id'],':r'=>$reason,':id'=>$id]);$q2=$dbh->prepare("UPDATE tblresult SET result_status='submitted',approval_state='rejected',Published=0,rejection_reason=:r,UpdationDate=NOW() WHERE submission_id=:id");$q2->execute([':r'=>$reason,':id'=>$id]);$dbh->commit();$msg='Submission rejected. Return it to the teacher when rework is required.';audit_log($dbh,'RESULT_REJECT','Submission '.$id); $n=$dbh->prepare('SELECT teacher_id,student_id,academic_year,term,exam_type FROM result_submissions WHERE id=:id');$n->execute([':id'=>$id]);if($nr=$n->fetch()){ $sq=$dbh->prepare('SELECT StudentName FROM tblstudents WHERE StudentId=:s');$sq->execute([':s'=>$nr['student_id']]);$sn=$sq->fetchColumn()?:'student'; notify_teacher($dbh,(int)$nr['teacher_id'],'Result rejected','Your result for '.$sn.' was rejected. Reason: '.$reason,'danger','teacher-submissions.php'); }}
elseif($action==='return'){ $q=$dbh->prepare("UPDATE result_submissions SET submission_status='rework',approval_state='pending',updated_at=NOW() WHERE id=:id AND submission_status='rejected'");$q->execute([':id'=>$id]);$q2=$dbh->prepare("UPDATE tblresult SET result_status='rework',approval_state='pending',Published=0,UpdationDate=NOW() WHERE submission_id=:id");$q2->execute([':id'=>$id]);$msg='Submission returned to teacher for rework.';audit_log($dbh,'RESULT_RETURN_REWORK','Submission '.$id); $n=$dbh->prepare('SELECT teacher_id,student_id,academic_year,term,exam_type,rejection_reason FROM result_submissions WHERE id=:id');$n->execute([':id'=>$id]);if($nr=$n->fetch()){ $sq=$dbh->prepare('SELECT StudentName FROM tblstudents WHERE StudentId=:s');$sq->execute([':s'=>$nr['student_id']]);$sn=$sq->fetchColumn()?:'student'; notify_teacher($dbh,(int)$nr['teacher_id'],'Result returned for rework','The result for '.$sn.' has been returned for rework. Reason: '.($nr['rejection_reason']?:'Please review the marks.'). '','warning','teacher-grade.php?student_id='.$nr['student_id'].'&class_id=0'); }}
elseif(in_array($action,['approve_teacher','approve_class'],true)){$teacher=(int)($_POST['teacher_id']??0);$class=(int)($_POST['class_id']??0);$where=$action==='approve_teacher'?'teacher_id=:t':'teacher_id=:t AND class_id=:c';$params=[':t'=>$teacher];if($action==='approve_class')$params[':c']=$class;$q=$dbh->prepare("SELECT id FROM result_submissions WHERE submission_status='pending' AND $where");$q->execute($params);$ids=$q->fetchAll(PDO::FETCH_COLUMN);foreach($ids as $sid)approve_submission($dbh,(int)$sid,(int)$_SESSION['admin_id']);$msg=count($ids).' pending submission(s) approved.';audit_log($dbh,'RESULT_BULK_APPROVE',$action.' teacher '.$teacher.($class?' class '.$class:''));}}
catch(Throwable $x){$error=$x->getMessage();}}
$teachers=$dbh->query('SELECT id,full_name FROM teachers WHERE status=1 ORDER BY full_name')->fetchAll();$classes=$dbh->query('SELECT id,ClassName,Section FROM tblclasses ORDER BY ClassNameNumeric,Section')->fetchAll();$q=$dbh->query('SELECT rs.*,t.full_name,s.StudentName,s.RollId,c.ClassName,c.Section FROM result_submissions rs JOIN teachers t ON t.id=rs.teacher_id JOIN tblstudents s ON s.StudentId=rs.student_id JOIN tblclasses c ON c.id=rs.class_id ORDER BY FIELD(rs.submission_status,\'pending\',\'rework\',\'rejected\',\'approved\'),rs.updated_at DESC');$rows=$q->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Result Approvals | SRMS</title><link rel="stylesheet" href="css/bootstrap.min.css"><link rel="stylesheet" href="css/font-awesome.min.css"><link rel="stylesheet" href="css/main.css"><link rel="stylesheet" href="css/srms-modernization.css"><link rel="stylesheet" href="css/srms-responsive.css"></head><body class="top-navbar-fixed"><div class="main-wrapper"><?php include 'includes/topbar.php';?><div class="content-wrapper"><div class="content-container"><?php include 'includes/leftbar.php';?><main class="main-page"><div class="container-fluid srms-page"><div class="srms-toolbar"><a href="dashboard.php" class="btn btn-default">← Dashboard</a><a href="manage-teachers.php" class="btn btn-primary">Teachers</a><a href="manage-results.php" class="btn btn-success">Publication</a></div><h2>Teacher Result Approvals</h2><?php if($msg):?><div class="alert alert-success"><?php echo e($msg);?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?php echo e($error);?></div><?php endif;?><div class="row"><div class="col-md-6"><form class="panel panel-default panel-body" method="post"><?php echo csrf_field();?><input type="hidden" name="action" value="approve_teacher"><label>Approve all pending results from teacher</label><select class="form-control" name="teacher_id" required><?php foreach($teachers as $t):?><option value="<?php echo $t['id'];?>"><?php echo e($t['full_name']);?></option><?php endforeach;?></select><button class="btn btn-success m-t-10">Approve Teacher Submissions</button></form></div><div class="col-md-6"><form class="panel panel-default panel-body" method="post"><?php echo csrf_field();?><input type="hidden" name="action" value="approve_class"><label>Approve all pending results for teacher + class</label><select class="form-control m-b-10" name="teacher_id" required><?php foreach($teachers as $t):?><option value="<?php echo $t['id'];?>"><?php echo e($t['full_name']);?></option><?php endforeach;?></select><select class="form-control" name="class_id" required><?php foreach($classes as $c):?><option value="<?php echo $c['id'];?>"><?php echo e($c['ClassName'].' '.$c['Section']);?></option><?php endforeach;?></select><button class="btn btn-success m-t-10">Approve Teacher/Class</button></form></div></div><div class="table-responsive"><table class="table table-bordered table-striped"><thead><tr><th>Teacher</th><th>Student</th><th>Class</th><th>Year</th><th>Exam</th><th>Status</th><th>Submitted</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?php echo e($r['full_name']);?></td><td><?php echo e($r['StudentName'].' ('.$r['RollId'].')');?></td><td><?php echo e($r['ClassName'].' '.$r['Section']);?></td><td><?php echo e($r['academic_year']);?></td><td><?php echo e($r['exam_type']);?></td><td><span class="label label-<?php echo $r['submission_status']==='approved'?'success':($r['submission_status']==='rejected'?'danger':($r['submission_status']==='rework'?'warning':'info'));?>"><?php echo e(result_status_label($r['submission_status']));?></span></td><td><?php echo e($r['submitted_at']??'—');?></td><td><?php if($r['submission_status']==='pending'):?><form method="post" class="inline-form"><?php echo csrf_field();?><input type="hidden" name="id" value="<?php echo $r['id'];?>"><button name="action" value="approve" class="btn btn-success btn-xs">Approve</button></form><button class="btn btn-danger btn-xs" data-toggle="modal" data-target="#reject<?php echo $r['id'];?>">Reject</button><?php elseif($r['submission_status']==='rejected'):?><form method="post" class="inline-form"><?php echo csrf_field();?><input type="hidden" name="id" value="<?php echo $r['id'];?>"><button name="action" value="return" class="btn btn-warning btn-xs">Return for Rework</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div><?php foreach($rows as $r):if($r['submission_status']!=='pending')continue;?><div class="modal fade" id="reject<?php echo $r['id'];?>"><div class="modal-dialog"><div class="modal-content"><form method="post"><?php echo csrf_field();?><div class="modal-header"><button type="button" class="close" data-dismiss="modal">&times;</button><h4>Reject Result</h4></div><div class="modal-body"><input type="hidden" name="id" value="<?php echo $r['id'];?>"><input type="hidden" name="action" value="reject"><textarea class="form-control" name="reason" rows="4" required placeholder="Explain what the teacher must correct..."></textarea></div><div class="modal-footer"><button class="btn btn-danger">Reject</button></div></form></div></div></div><?php endforeach;?></main></div></div></div></div><script src="js/jquery/jquery-2.2.4.min.js"></script><script src="js/bootstrap/bootstrap.min.js"></script></body></html>
